/**
 * Deterministic fixture construction.
 *
 * ULIDs are generated by a local factory instead of `core.newId` because
 * `newId` keeps process-global monotonic state (correct for production, but a
 * source of cross-test coupling). The factory derives its random component from
 * a seed plus the ULID millisecond, so the same builder options produce the
 * same identifier sequence in any process.
 *
 * Hashes are computed with the production canonicalizer so fixtures contain
 * real `sha256:<64 hex>` values. They are inputs to the code under test, not an
 * oracle: expected hashes in tests must come from independent vectors
 * (testing design TST 5.2).
 */

import { createHash } from "node:crypto";

import {
  canonicalHash,
  canonicalJsonText,
  hashUtf8,
  isRegisteredPrefix,
  makeGoalVersion,
  parseHash,
  versionBindingKey,
  assertJsonValue,
  type ConfigVersion,
  type GoalVersion,
  type Hash,
  type Id,
  type IdPrefix,
  type JsonValue,
  type Ulid,
  type VersionBinding
} from "@evoplug/core";

import { FakeClock } from "./clock.js";

const CROCKFORD_ALPHABET = "0123456789ABCDEFGHJKMNPQRSTVWXYZ";
const ULID_TIME_MAX = 281_474_976_710_655;
const ULID_RANDOM_BITS = 80n;
const ULID_RANDOM_MASK = (1n << ULID_RANDOM_BITS) - 1n;

interface DeterministicUlidOptions {
  /** Seed for the random component. Defaults to a fixed test-support seed. */
  readonly seed?: string;
  /** First millisecond used when `next` is called without an explicit time. */
  readonly startTimeMs?: number;
}

function assertUlidTime(timeMs: number): void {
  if (!Number.isSafeInteger(timeMs) || timeMs < 0 || timeMs > ULID_TIME_MAX) {
    throw new RangeError(`timeMs must be an integer in 0..${String(ULID_TIME_MAX)}, received ${String(timeMs)}`);
  }
}

function seedRandom(seed: string, timeMs: number): bigint {
  const digest = createHash("sha256").update(`${seed}\u0000${String(timeMs)}`, "utf8").digest();
  let value = 0n;
  for (let index = 0; index < 10; index += 1) {
    value = (value << 8n) | BigInt(digest[index] ?? 0);
  }
  return value & ULID_RANDOM_MASK;
}

function characterAt(index: number): string {
  const character = CROCKFORD_ALPHABET.charAt(index);
  if (character === "") {
    throw new RangeError(`ULID alphabet index out of range: ${String(index)}`);
  }
  return character;
}

function encodeUlid(timeMs: number, random: bigint): Ulid {
  let remainingTime = timeMs;
  const timeChars: string[] = new Array<string>(10);
  for (let index = 9; index >= 0; index -= 1) {
    timeChars[index] = characterAt(remainingTime % 32);
    remainingTime = Math.floor(remainingTime / 32);
  }
  let remainingRandom = random;
  const randomChars: string[] = new Array<string>(16);
  for (let index = 15; index >= 0; index -= 1) {
    randomChars[index] = characterAt(Number(remainingRandom & 31n));
    remainingRandom >>= 5n;
  }
  return `${timeChars.join("")}${randomChars.join("")}` as Ulid;
}

/**
 * Seed-deterministic, same-process-monotonic ULID factory.
 *
 * Calls at the same millisecond increment the 80-bit random component. A
 * backwards request reuses the last millisecond, matching the production
 * `newId` contract.
 */
export class DeterministicUlidFactory {
  private readonly seed: string;
  private readonly startTimeMs: number;
  private lastTimeMs: number;
  private lastRandom: bigint;

  constructor(options: DeterministicUlidOptions = {}) {
    this.seed = options.seed ?? "evoplug.test-support";
    this.startTimeMs = options.startTimeMs ?? 0;
    assertUlidTime(this.startTimeMs);
    this.lastTimeMs = -1;
    this.lastRandom = 0n;
  }

  /** Next ULID. `atMs` defaults to the configured start millisecond. */
  next(atMs: number = this.startTimeMs): Ulid {
    assertUlidTime(atMs);
    let timeMs = atMs;
    if (timeMs > this.lastTimeMs) {
      this.lastTimeMs = timeMs;
      this.lastRandom = seedRandom(this.seed, timeMs);
    } else {
      timeMs = this.lastTimeMs;
      this.lastRandom = (this.lastRandom + 1n) & ULID_RANDOM_MASK;
      if (this.lastRandom === 0n) {
        this.lastTimeMs += 1;
        if (this.lastTimeMs > ULID_TIME_MAX) {
          throw new RangeError("ULID timestamp overflow");
        }
        timeMs = this.lastTimeMs;
      }
    }
    return encodeUlid(timeMs, this.lastRandom);
  }

  /** Next `<prefix>:<ULID>`. */
  nextId<P extends IdPrefix>(prefix: P, atMs: number = this.startTimeMs): Id<P> {
    if (!isRegisteredPrefix(prefix)) {
      throw new RangeError(`unknown id prefix ${JSON.stringify(prefix)}`);
    }
    return `${prefix}:${this.next(atMs)}` as Id<P>;
  }
}

/** Stable starter config used by `configVersion` when no content is supplied. */
const DEFAULT_FIXTURE_CONFIG: JsonValue = {
  schema_version: "rsi.fixture_config/1",
  config_space: "default"
};

function cloneJson(value: JsonValue): JsonValue {
  if (value === null || typeof value !== "object") {
    return value;
  }
  if (Array.isArray(value)) {
    const items: JsonValue[] = [];
    for (const item of value) {
      items.push(cloneJson(item));
    }
    return items;
  }
  const object: { [key: string]: JsonValue } = {};
  for (const [key, item] of Object.entries(value)) {
    object[key] = cloneJson(item);
  }
  return object;
}

interface FixtureBuilderOptions {
  /** Seed for deterministic ULIDs. Defaults to `evoplug.test-support`. */
  readonly seed?: string;
  /** Initial monotonic reading and ULID time base. Defaults to 0. */
  readonly startTimeMs?: number;
  /** Initial wall-clock epoch. Defaults to 0. */
  readonly startUtcMs?: number;
  /** Fixed task ID; when omitted the builder allocates the first ULID. */
  readonly taskId?: Id<"task">;
  /** Fixed branch ID; when omitted the builder allocates the next ULID. */
  readonly branchId?: Id<"br">;
  /** Reserved for callers that want to document a starting revision. */
  readonly goalRevision?: number;
  /** Config content used by the default `config_version`. */
  readonly configContent?: JsonValue;
  /** Default `input_epoch` in `versionBinding`. Defaults to 1. */
  readonly inputEpoch?: number;
  /** Default `watermark` in `versionBinding`. Defaults to 0. */
  readonly watermark?: number;
}

interface FixtureVersionBindingOptions {
  readonly task_id?: Id<"task">;
  readonly branch_id?: Id<"br">;
  readonly input_epoch?: number;
  readonly goal_version?: GoalVersion;
  readonly config_version?: ConfigVersion;
  readonly watermark?: number;
}

/**
 * Builds deterministic fixtures around one task/branch pair and one clock.
 *
 * ID calls consume the deterministic sequence in call order. `taskId` and
 * `branchId` are allocated in the constructor (unless supplied), so subsequent
 * IDs are stable for a given option set.
 */
class FixtureBuilder {
  readonly clock: FakeClock;
  readonly ulids: DeterministicUlidFactory;
  readonly taskId: Id<"task">;
  readonly branchId: Id<"br">;
  private readonly defaultConfig: JsonValue;
  private readonly defaultGoalRevision: number;
  private readonly defaultInputEpoch: number;
  private readonly defaultWatermark: number;

  constructor(options: FixtureBuilderOptions = {}) {
    this.clock = new FakeClock({
      startMonotonicMs: options.startTimeMs ?? 0,
      startUtcMs: options.startUtcMs ?? 0
    });
    this.ulids = new DeterministicUlidFactory({
      seed: options.seed ?? "evoplug.test-support",
      startTimeMs: options.startTimeMs ?? 0
    });
    this.taskId = options.taskId ?? this.ulids.nextId("task", this.clock.utcNowMs());
    this.branchId = options.branchId ?? this.ulids.nextId("br", this.clock.utcNowMs());
    this.defaultConfig = cloneJson(options.configContent ?? DEFAULT_FIXTURE_CONFIG);
    this.defaultGoalRevision = options.goalRevision ?? 1;
    if (!Number.isSafeInteger(this.defaultGoalRevision) || this.defaultGoalRevision < 1) {
      throw new RangeError(
        `goalRevision must be a positive safe integer, received ${String(this.defaultGoalRevision)}`
      );
    }
    this.defaultInputEpoch = options.inputEpoch ?? 1;
    this.defaultWatermark = options.watermark ?? 0;
  }

  /** Next ULID on the builder clock's wall time. */
  ulid(): Ulid {
    return this.ulids.next(this.clock.utcNowMs());
  }

  /** Next registered ID on the builder clock's wall time. */
  id<P extends IdPrefix>(prefix: P): Id<P> {
    return this.ulids.nextId(prefix, this.clock.utcNowMs());
  }

  /** `sha256(JCS(value))`. */
  hash(value: JsonValue): Hash {
    return canonicalHash(value);
  }

  /** `sha256(UTF-8 text)`, for payload and range hashes. */
  hashText(text: string): Hash {
    return hashUtf8(text);
  }

  /** Validates and deep-clones a JSON value so fixtures do not alias inputs. */
  jsonValue(value: JsonValue): JsonValue {
    assertJsonValue(value);
    return cloneJson(value);
  }

  /** Canonical JSON text, for byte-level fixture comparisons. */
  jsonText(value: JsonValue): string {
    return canonicalJsonText(value);
  }

  /** `gv:<branchId>:<revision>`, revision starting at 1. */
  goalVersion(revision: number = 1): GoalVersion {
    return makeGoalVersion(this.branchId, revision);
  }

  /** `cfgv:sha256:<64 hex>` over the config content. */
  configVersion(content: JsonValue = this.defaultConfig): ConfigVersion {
    return `cfgv:${this.hash(content)}`;
  }

  /** Valid default binding with per-field overrides. */
  versionBinding(overrides: FixtureVersionBindingOptions = {}): VersionBinding {
    return {
      task_id: overrides.task_id ?? this.taskId,
      branch_id: overrides.branch_id ?? this.branchId,
      input_epoch: overrides.input_epoch ?? this.defaultInputEpoch,
      goal_version: overrides.goal_version ?? this.goalVersion(this.defaultGoalRevision),
      config_version: overrides.config_version ?? this.configVersion(),
      watermark: overrides.watermark ?? this.defaultWatermark
    };
  }

  /** Canonical binding key used for cache and equality checks. */
  bindingKey(binding: VersionBinding): Hash {
    return versionBindingKey(binding);
  }

  /** Re-validates a hash supplied by a test or fixture file. */
  parseHash(value: string): Hash {
    return parseHash(value);
  }
}

/** Creates a fixture builder with deterministic IDs, hashes and clock. */
export function createFixtureBuilder(options: FixtureBuilderOptions = {}): FixtureBuilder {
  return new FixtureBuilder(options);
}
